import{_ as e,o as t,c as l,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"约翰·古尔特弗里德","description":"","frontmatter":{"title":"约翰·古尔特弗里德","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/约翰·古尔特弗里德.md","filePath":"04_people/约翰·古尔特弗里德.md"}'),o={name:"04_people/约翰·古尔特弗里德.md"};function i(s,a,n,_,h,c){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="约翰·古尔特弗里德" tabindex="-1">约翰·古尔特弗里德 <a class="header-anchor" href="#约翰·古尔特弗里德" aria-label="Permalink to &quot;约翰·古尔特弗里德&quot;">​</a></h1><ul><li><strong>角色职位</strong>：所罗门兄弟（Salomon Inc.）CEO</li><li><strong>与巴菲特关系</strong>：1991年国债丑闻期间担任所罗门兄弟CEO，巴菲特临危受命介入救援</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>约翰·古尔特弗里德在1991年担任所罗门兄弟CEO期间，经历了这家公司历史上最严峻的危机——国债拍卖丑闻。1991年，所罗门兄弟因在国债拍卖中违规投标而遭受调查，公司一度濒临崩溃边缘。这起事件将所罗门兄弟和整个美国金融市场都推向了动荡之中。</p><p>就在危机最严重的时刻，沃伦·巴菲特以&quot;紧急救火队员&quot;的身份介入所罗门兄弟。巴菲特不仅是所罗门的大股东，更在危机关头亲自致电财政部保证公司信誉，并派驻芒格等人协助稳定局势。古尔特弗里德作为时任CEO，在这场危机中承受着巨大的压力。</p><p>巴菲特最终在1991年9月亲自担任所罗门临时董事长，直到公司度过最困难的时期。这段经历成为巴菲特商业生涯中少数几次直接介入日常管理的案例。虽然古尔特弗里德最终离任，但所罗门兄弟最终在巴菲特的主导下稳定下来，并在此后保持了相对稳健的发展。古尔特弗里德亲历的这场危机，也成为后来巴菲特在股东信中反复提及的风险管理案例。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1991年</strong>：担任所罗门兄弟CEO，遭遇国债拍卖违规丑闻</li><li><strong>1991年</strong>：丑闻曝光后辞任CEO，巴菲特介入担任临时董事长</li><li><strong>1991年后</strong>：离开所罗门，所罗门在巴菲特主导下度过危机</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=ISCAR收购">2006年：完整翻译|/01_letters/2006年/翻译</a></li><li><a href="/search.html?q=ISCAR经营">2007年：完整翻译|/01_letters/2007年/翻译</a></li><li><a href="/search.html?q=ISCAR更新">2010年：完整翻译|/01_letters/2010年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",i]]);export{d as __pageData,u as default};
